package cl.bolsillo.app;
import android.content.*;import org.json.*;import java.util.*;import java.security.*;
final class Detection {
 static JSONArray sources(Context c){try{String raw=NativeStore.settings(c).getString("sources","");if(!raw.isEmpty())return new JSONArray(raw);JSONArray list=new JSONArray();for(String bank:new String[]{"bancoestado","mach"}){String pkg=NativeStore.settings(c).getString(bank,"");if(!pkg.isEmpty())list.put(new JSONObject().put("package",pkg).put("label",NativeStore.settings(c).getString(bank+"Label",bank)).put("kind",bank).put("account",""));}return list;}catch(Exception e){return new JSONArray();}}
 static JSONObject source(Context c,String pkg){JSONArray list=sources(c);for(int i=0;i<list.length();i++){JSONObject s=list.optJSONObject(i);if(s!=null&&s.optBoolean("enabled",true)&&pkg.equals(s.optString("package")))return s;}return null;}
 static String account(Context c,JSONObject data,JSONObject source,String last4)throws Exception{return NotificationRouting.resolve(data.getJSONArray("accounts"),source,last4,PaymentCards.suffixes(c,data.getJSONArray("accounts")));}
 static String category(Context c,JSONObject data,String merchant)throws Exception{JSONArray cats=data.getJSONArray("categories"),rules=new JSONArray(NativeStore.settings(c).getString("categoryRules","[]"));String text=BankNotificationParser.normalize(merchant),chosen="";for(int i=0;i<rules.length();i++){JSONObject r=rules.getJSONObject(i);if(text.contains(BankNotificationParser.normalize(r.optString("word")))&&!r.optString("word").trim().isEmpty()){chosen=r.optString("category");break;}}
 String[][] defaults={{"netflix|spotify|youtube|disney|hbo|prime video","expense-7"},{"supermercado|lider|jumbo|unimarc|santa isabel|restaurant|cafe|cafeteria|mcdonald|burger|pedidosya|rappi","expense-0"},{"uber|cabify|didi|metro|bip|copec|shell|bencina","expense-1"},{"farmacia|cruz verde|salcobrand|ahumada|clinica","expense-3"},{"falabella|ripley|paris|mercado libre|amazon|aliexpress","expense-4"}};
 if(chosen.isEmpty())chosen=ConceptCatalog.preferredCategory(data,"expense",merchant);
 if(chosen.isEmpty())for(String[] rule:defaults){for(String term:rule[0].split("\\|"))if(text.contains(term)){chosen=rule[1];break;}if(!chosen.isEmpty())break;}String fallback="";for(int i=0;i<cats.length();i++){JSONObject x=cats.getJSONObject(i);if(!"expense".equals(x.optString("type"))||x.optBoolean("archived"))continue;String id=x.getString("id");if(id.equals(chosen))return id;if(fallback.isEmpty()||id.equals("expense-8"))fallback=id;}return fallback;}
 static String incomeCategory(JSONObject data)throws Exception{JSONArray cats=data.getJSONArray("categories");String fallback="";for(int i=0;i<cats.length();i++){JSONObject x=cats.getJSONObject(i);if(x.optString("type").equals("income")&&!x.optBoolean("archived")){if(x.optString("id").equals("income-3"))return x.getString("id");if(fallback.isEmpty())fallback=x.getString("id");}}return fallback;}
 static String hash(String text)throws Exception{byte[] b=MessageDigest.getInstance("SHA-256").digest(text.getBytes("UTF-8"));StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x&255));return s.toString();}
 static void status(Context c,String label,String message){NativeStore.settings(c).edit().putString("lastDetection",label+" · "+message).putLong("lastDetectionAt",System.currentTimeMillis()).apply();}
 static void accept(Context c,JSONObject source,BankNotificationParser.Candidate candidate,String key,long at)throws Exception{ synchronized(NativeStore.class){ if(!NativeStore.settings(c).getBoolean("capture",false)||Detection.source(c,source.optString("package"))==null)return;
 JSONObject cache=NativeStore.cached(c);if(cache==null){status(c,source.optString("label"),"Abre Bolsillo primero");return;}JSONObject data=cache.getJSONObject("data");String owner=cache.optString("ownerId"),from=account(c,data,source,candidate.last4),category=candidate.type.equals("income")?incomeCategory(data):category(c,data,candidate.merchant),pkg=source.getString("package");String fingerprint=hash(pkg+"|"+key+"|"+at+"|"+candidate.amount+"|"+candidate.merchant+"|"+candidate.type);JSONObject state=NativeStore.state(c);JSONArray seen=state.optJSONArray("seen");if(seen!=null)for(int i=0;i<seen.length();i++)if(fingerprint.equals(seen.optString(i)))return;
 JSONObject evidence=new JSONObject().put("id",fingerprint).put("ownerId",owner).put("type",candidate.type).put("review",candidate.review).put("amount",candidate.amount).put("merchant",candidate.merchant).put("last4",candidate.last4).put("account",from).put("category",category).put("source",pkg).put("label",source.optString("label")).put("at",at).put("reference",candidate.reference).put("key",hash(pkg+"|"+key));
 Set<String> transactionIds=new HashSet<>(),inboxIds=new HashSet<>();JSONArray existingTransactions=data.getJSONArray("transactions"),currentInbox=state.optJSONArray("detectionInbox");for(int i=0;i<existingTransactions.length();i++)transactionIds.add(existingTransactions.getJSONObject(i).optString("id"));if(currentInbox!=null)for(int i=0;i<currentInbox.length();i++)inboxIds.add(currentInbox.getJSONObject(i).optString("id"));
 String duplicate="";int confidence=0;JSONArray events=state.optJSONArray("detectionEvents");if(events!=null)for(int i=events.length()-1;i>=0;i--){JSONObject old=events.getJSONObject(i);if(!owner.equals(old.optString("ownerId"))||!candidate.type.equals(old.optString("type","expense")))continue;boolean existing=transactionIds.contains(old.optString("txId")),pending=inboxIds.contains(old.optString("id"));
  if((existing||pending)&&BankNotificationParser.safeDuplicate(candidate.reference,old.optString("reference"),candidate.amount,old.optLong("amount"),from,old.optString("account"),candidate.type,old.optString("type"),at,old.optLong("at"))){evidence.put("suppressed",true).put("duplicateOf",old.optString("txId")).put("duplicateEvidence",old.optString("id")).put("txId",old.optString("txId")).put("reason",existing?"Misma referencia, cuenta y monto: ya registrado":"Misma referencia: unido al aviso pendiente");NativeStore.saveDetection(c,evidence,null);status(c,source.optString("label"),existing?"Aviso duplicado unido al movimiento existente":"Aviso duplicado unido a la revisión pendiente");return;}
  if(!existing)continue;
  if(!candidate.reference.isEmpty()&&!old.optString("reference").isEmpty()&&!candidate.reference.equals(old.optString("reference")))continue;
  int score=BankNotificationParser.duplicate(candidate.amount,from,candidate.merchant,at,pkg,old.optLong("amount"),old.optString("account"),old.optString("merchant"),old.optLong("at"),old.optString("source"));
  // A reused bank notification key alone does not prove that two purchases are one.
  if(score>confidence){duplicate=old.optString("txId");confidence=score;}}
 // Previously entered expenses can overlap a bank alert. Keep these for review.
 JSONArray txs=data.getJSONArray("transactions");if(confidence==0&&!from.isEmpty())for(int i=txs.length()-1;i>=0;i--){JSONObject t=txs.getJSONObject(i);if(candidate.type.equals(t.optString("type"))&&"posted".equals(t.optString("status"))&&from.equals(t.optString("account"))&&candidate.amount==t.optLong("amount")&&date(at).equals(t.optString("date"))&&!"notification".equals(t.optString("source"))){duplicate=t.optString("id");confidence=1;break;}}
 String mode=LearnedRules.mode(data,NativeStore.settings(c).getBoolean("autoPost",true));LearnedRules.Match learned=LearnedRules.match(data,evidence);String learnedReason="";
 if(learned!=null){if(learned.ready){evidence.put("category",learned.rule.optString("category")).put("learnedRule",learned.rule.optString("id")).put("learnedExplanation",LearnedRules.explanation(learned.rule));category=evidence.optString("category");}else if(learned.rule.optBoolean("conflict")||learned.rule.optJSONArray("exampleIds").length()>=LearnedRules.threshold(data))learnedReason=learned.reason;}
 String reason=!candidate.reason.isEmpty()?candidate.reason:candidate.amount<=0?"Confirma el monto en pesos enteros":candidate.type.equals("unknown")?"Elige ingreso o gasto":from.isEmpty()?"Elige la cuenta":category.isEmpty()?"Elige una categoría":confidence>0?"Posible duplicado: revisa ambos movimientos":candidate.review?"Confirma el tipo de movimiento y su cuenta":!learnedReason.isEmpty()?learnedReason:mode.equals("review")?"Elegiste revisar siempre":mode.equals("patterns")&&(learned==null||!learned.ready)?"Patrón aún sin suficientes confirmaciones":"";
 if(!reason.isEmpty()){evidence.put("reason",reason).put("duplicateOf",duplicate);NativeStore.saveDetection(c,evidence,null);status(c,source.optString("label"),reason+" · Revisión");}
 else{JSONObject tx=transaction(c,evidence,true);evidence.put("txId",tx.getString("id"));NativeStore.saveDetection(c,evidence,tx);status(c,source.optString("label"),evidence.has("learnedRule")?"Registrado por tu patrón confirmado":"Movimiento registrado automáticamente");NativeSync.run(c,null);}
 BolsilloWidget.updateAll(c);
 }
 }
 static String date(long at){return java.time.Instant.ofEpochMilli(at).atZone(java.time.ZoneId.of("America/Santiago")).toLocalDate().toString();}
 static JSONObject transaction(Context c,JSONObject e,boolean posted)throws Exception{JSONObject tx=NativeSync.transaction(e.optString("type","expense"),e.getLong("amount"),e.getString("account"),"",e.getString("category"),e.getString("merchant"),"notification",e.getString("id"));tx.put("date",date(e.getLong("at"))).put("status",posted?"posted":"pending").put("detectedAt",e.getLong("at")).put("detectedSource",e.optString("label")).put("detectionId",e.optString("id")).put("detectedReference",e.optString("reference"));if(e.has("learnedRule"))tx.put("learnedRule",e.optString("learnedRule")).put("learnedExplanation",e.optString("learnedExplanation"));return tx;}
}



